class Solution {
    bool isPal(long long x, int k) {
        long long r = 0, t = x;
        while (t > 0) { r = r * k + t % k; t /= k; }
        return r == x;
    }
public:
    long long kMirror(int k, int n) {
        long long sum = 0;
        for (int len = 1; n > 0; ++len) {
            int half = (len + 1) / 2;
            long long lo = 1;
            for (int i = 1; i < half; ++i) lo *= 10;
            long long hi = lo * 10;
            for (long long root = lo; root < hi && n > 0; ++root) {
                long long p = root;
                long long t = (len % 2 == 1) ? root / 10 : root;
                while (t > 0) { p = p * 10 + t % 10; t /= 10; }
                if (isPal(p, k)) { sum += p; --n; }
            }
        }
        return sum;
    }
};
